import axios from 'axios';
import { app, BrowserWindow, dialog, ipcMain, Menu, protocol, shell } from 'electron';
import * as fs from 'fs';
import * as keytar from 'keytar';
import * as path from 'path';
import { ACCOUNT_NAME, SERVICE_NAME, UPDATE_PREFERENCE_KEY } from './constants/settings-keys';
import { baseApi } from './utils/environment';
import { getHardwareInfo } from './utils/hwid';
import { getSimpleHwid } from './utils/mac';

// import env
import * as dotenv from 'dotenv';
dotenv.config();

// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

// Keys for settings
const SETTINGS_FILE = path.join(app.getPath('userData'), 'settings.json');

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require('electron-squirrel-startup')) {
  app.quit();
}

// Persistent settings store
const persistentStore: Record<string, string> = {};

// Load settings from file
function loadSettings() {
  try {
    if (fs.existsSync(SETTINGS_FILE)) {
      const data = fs.readFileSync(SETTINGS_FILE, 'utf8');
      const settings = JSON.parse(data);
      Object.assign(persistentStore, settings);
      console.log('Settings loaded from', SETTINGS_FILE);
    }
  } catch (error) {
    console.error('Failed to load settings:', error);
  }
}

// Save settings to file
function saveSettings() {
  try {
    fs.writeFileSync(SETTINGS_FILE, JSON.stringify(persistentStore), 'utf8');
    console.log('Settings saved to', SETTINGS_FILE);
  } catch (error) {
    console.error('Failed to save settings:', error);
  }
}

const createWindow = (): void => {
  // Create the browser window.
  const mainWindow = new BrowserWindow({
    width: 1440,
    height: 900,
    frame: true,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      nodeIntegration: true, // Deshabilitado por seguridad
      contextIsolation: true, // Asegura el aislamiento de contexto
      sandbox: false,
      devTools: app.isPackaged ? false : true,
    },
  });

  if (app.isPackaged) {
    Menu.setApplicationMenu(null);
  }

  // Set CSP headers
  mainWindow.webContents.session.webRequest.onHeadersReceived((details, callback) => {
    callback({
      responseHeaders: {
        ...details.responseHeaders,
        'Content-Security-Policy': [
          "default-src 'self';",
          "script-src 'self' 'unsafe-inline' 'unsafe-eval';", // unsafe-eval needed for CodeMirror
          "style-src 'self' 'unsafe-inline';",
          "img-src 'self' data: blob:;",
          `connect-src 'self' ${baseApi};`,
          "worker-src 'self' blob:;",
          "media-src 'self' static:;",
        ].join(' '),
      },
    });
  });

  // and load the index.html of the app.
  mainWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY);

  // Open the DevTools.
  mainWindow.webContents.openDevTools();
};

// Set up IPC handlers for secure storage
function setupSecureStore() {
  ipcMain.handle('get-secure-store', async (_, key: string) => {
    try {
      return await keytar.getPassword(SERVICE_NAME, ACCOUNT_NAME);
    } catch (error) {
      console.error('Failed to retrieve from secure store:', error);
      return null;
    }
  });

  ipcMain.handle('set-secure-store', async (_, key: string, value: string) => {
    try {
      await keytar.setPassword(SERVICE_NAME, ACCOUNT_NAME, value);
      return true;
    } catch (error) {
      console.error('Failed to store securely:', error);
      return false;
    }
  });

  ipcMain.handle('delete-secure-store', async (_, key: string) => {
    try {
      await keytar.deletePassword(SERVICE_NAME, ACCOUNT_NAME);
      return true;
    } catch (error) {
      console.error('Failed to delete from secure store:', error);
      return false;
    }
  });

  // Add store handlers for general settings
  ipcMain.handle('get-store', async (_, key: string) => {
    try {
      return persistentStore[key] || null;
    } catch (error) {
      console.error(`Failed to get ${key} from store:`, error);
      return null;
    }
  });

  ipcMain.handle('set-store', async (_, key: string, value: string) => {
    try {
      persistentStore[key] = value;
      saveSettings();
      return true;
    } catch (error) {
      console.error(`Failed to set ${key} in store:`, error);
      return false;
    }
  });

  ipcMain.handle('delete-store', async (_, key: string) => {
    try {
      delete persistentStore[key];
      saveSettings();
      return true;
    } catch (error) {
      console.error(`Failed to delete ${key} from store:`, error);
      return false;
    }
  });

  // Add env handler
  ipcMain.handle('get-env', async (_, key: string) => {
    return process.env[key] || '';
  });

  ipcMain.handle('getHardwareInfo', async () => {
    return await getHardwareInfo();
  });

  ipcMain.handle('getSimpleHwid', () => {
    return getSimpleHwid();
  });
}

async function checkForUpdates() {
  try {
    // Check user preference for updates
    // Default to true if preference is not set
    const updatesEnabled =
      persistentStore[UPDATE_PREFERENCE_KEY] === undefined
        ? true
        : persistentStore[UPDATE_PREFERENCE_KEY] === 'true';

    console.log('Updates enabled:', updatesEnabled);

    // Skip update check if user has disabled updates
    if (!updatesEnabled) {
      console.log('Updates are disabled by user preference');
      return;
    }

    const response = await axios.get(baseApi + '/api/version');
    const latestVersion = response.data.version;
    const currentVersion = app.getVersion();

    console.log('latestVersion', latestVersion);
    console.log('currentVersion', currentVersion);

    if (latestVersion !== currentVersion) {
      dialog
        .showMessageBox({
          type: 'info',
          buttons: ['Download', 'Ignore'],
          title: 'New version available',
          message: `New version ${latestVersion} available`,
          detail: response.data.releaseNotes || 'Update for new features!',
        })
        .then((response) => {
          if (response.response === 0) {
            shell.openExternal(baseApi + '/downloads');
          }
        });
    }
  } catch (err) {
    console.error('Error checking version');
  }
}

function registerLocalSoundProtocol() {
  protocol.registerFileProtocol('static', (request, callback) => {
    const fileUrl = request.url.replace('static://', '');
    const filePath = path.join(app.getAppPath(), '.webpack/renderer', fileUrl);
    callback(filePath);
  });
}

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
app.whenReady().then(async () => {
  registerLocalSoundProtocol();
  loadSettings();
  setupSecureStore();
  createWindow();
  checkForUpdates();

  // Quit when all windows are closed, except on macOS. There, it's common
  // for applications and their menu bar to stay active until the user quits
  // explicitly with Cmd + Q.
  app.on('window-all-closed', () => {
    if (process.platform !== 'darwin') {
      app.quit();
    }
  });

  app.on('activate', () => {
    // On OS X it's common to re-create a window in the app when the
    // dock icon is clicked and there are no other windows open.
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });

  // In this file you can include the rest of your app's specific main process
  // code. You can also put them in separate files and import them here.
});
